{
  "units": [
    {
      "title": "Interest Rate Differential and Expected Exchange Rate",
      "source_segment_ids": ["CON_0032"],
      "mode": "text_and_visual",
      "remaining_text": "",
      "visuals": [
        {
          "type": "table",
          "source_segment_ids": ["CON_0032"],
          "needs_review": false,
          "missing_information": false,
          "evidence": [
            {
              "note_id": "CON_0032",
              "quote": "If the domestic interest rate is above the international interest rate, the exchange rate today must be above the expected exchange rate, giving an expected depreciation that compensates for the higher domestic bond yield."
            },
            {
              "note_id": "CON_0032",
              "quote": "Conversely, if the domestic bond is paying a lower interest rate, then the exchange rate today is very depreciated because you have to expect it to appreciate in order to compensate for the interest rate differential."
            }
          ],
          "payload": {
            "type": "table",
            "title": "Domestic vs. Foreign Interest Rate Effects",
            "headers": ["Domestic Interest vs. Foreign", "Spot Exchange Rate vs. Expected", "Implication"],
            "rows": [
              [
                "Domestic > Foreign",
                "Spot > Expected",
                "Expected depreciation of domestic currency"
              ],
              [
                "Domestic = Foreign",
                "Spot = Expected",
                "No expected currency movement"
              ],
              [
                "Domestic < Foreign",
                "Spot < Expected",
                "Expected appreciation of domestic currency"
              ]
            ]
          }
        }
      ]
    }
  ]
}
